#include <stdio.h>

typedef struct {
    int nb_refs[2];
} HEVCContext;

void process_reference_weights(HEVCContext *s) {
    // Fixed-size stack arrays as per HEVC spec (max 16 references)
    int luma_weight_l0_flag[16];
    int chroma_weight_l0_flag[16];

    // VULNERABILITY: nb_refs[L0] is taken directly from the bitstream
    // without validating it against the maximum allowed value (16).
    int count = s->nb_refs[0];

    // Loop iterates 'count' times, writing to arrays of size 16.
    // If count > 16, this causes a stack buffer overflow.
    for (int i = 0; i < count; i++) {
        luma_weight_l0_flag[i] = 1;
        chroma_weight_l0_flag[i] = 0;
    }
}

int main() {
    HEVCContext ctx = {0};
    // Simulate crafted bitstream input where nb_refs[L0] exceeds spec limit
    ctx.nb_refs[0] = 20; // Exploit: value >= 16 triggers OOB write

    printf("Simulating loop with count=%d (max safe: 16)\n", ctx.nb_refs[0]);
    process_reference_weights(&ctx);
    printf("Loop completed. In a real decoder, this would corrupt adjacent stack memory.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned char *buf[3];
    int reference;
} Picture;

typedef struct {
    Picture *f;
} DPBEntry;

typedef struct {
    DPBEntry DPB[16];
    int size;
} H264Context;

// Vulnerable cleanup loop
void release_unused_pictures(H264Context *h) {
    for (int i = 0; i < h->size; i++) {
        // EXPLOIT MECHANISM: The code dereferences h->DPB[i].f->buf[0] without checking if h->DPB[i].f is NULL.
        // A malformed bitstream can manipulate codec state to leave a DPB entry's 'f' pointer as NULL.
        // When this loop executes, the missing validation causes a NULL pointer dereference (crash/DoS).
        if (h->DPB[i].f->buf[0] && !h->DPB[i].reference) {
            h->DPB[i].f->buf[0] = NULL;
        }
    }
}

int main() {
    H264Context h = {0};
    h.size = 2;
    h.DPB[0].f = malloc(sizeof(Picture));
    h.DPB[0].f->buf[0] = malloc(100);
    h.DPB[0].f->reference = 0;

    // Simulate crafted input leaving DPB[1].f as NULL
    h.DPB[1].f = NULL;
    h.DPB[1].reference = 0;

    // Trigger vulnerability
    release_unused_pictures(&h);
    return 0;
}

