    // The multiplication b4_stride * mb_height * 4 exceeds INT32_MAX (2,147,483,647)
    // and wraps around to a small positive value due to 32-bit signed integer overflow.
    // No overflow check is performed before allocation.
    int allocated_size = b4_stride * mb_height * 4;

    printf("Expected logical size: %lld bytes\n", (long long)b4_stride * mb_height * 4);
    printf("Overflowed allocation size: %d bytes\n", allocated_size);

    // Allocate buffer based on the wrapped (small) size
    uint8_t *heap_buf = malloc(allocated_size);
    if (!heap_buf) return 1;

    // EXPLOIT MECHANISM:
    // The decoder later assumes the buffer is large enough for the logical dimensions.
    // Any write operation using the original large size (e.g., memset, memcpy, or direct indexing)
    // will write beyond the allocated heap region, causing a heap buffer overflow.
    // In a real scenario: memcpy(heap_buf, decoded_data, b4_stride * mb_height * 4);
    printf("Vulnerability demonstrated: %lld-byte logical write would overflow %d-byte heap allocation.\n",
           (long long)b4_stride * mb_height * 4, allocated_size);

    free(heap_buf);
    return 0;
}

