typedef struct {
    const uint8_t *buf;
    int buf_size;
} ProbeData;

// Minimal proof-of-concept demonstrating the out-of-bounds read vulnerability
int mpegps_probe_poc(const ProbeData *p) {
    for (int i = 0; i < p->buf_size; i++) {
        // Detect MPEG-PS start code (0x00 0x00 0x01)
        if (p->buf[i] == 0x00 && p->buf[i+1] == 0x00 && p->buf[i+2] == 0x01) {
            // VULNERABILITY: The code proceeds to read subsequent bytes
            // without verifying that i+1 and i+2 are within [0, buf_size).
            // When the start code is placed at the very end of the buffer,
            // these accesses read beyond the allocated memory.
            uint8_t val1 = p->buf[i + 1]; // Out-of-bounds if i == buf_size - 1
            uint8_t val2 = p->buf[i + 2]; // Out-of-bounds if i == buf_size - 2
            (void)val1;
            (void)val2;
            return 1; // Signal valid MPEG stream
        }
    }
    return 0;
}

